  --text-dim: #9aa3b8;
  --text-muted: #6b748a;
  --accent: #6c8cff;
  --danger: #ef4444;
  --danger-strong: #dc2626;
  --danger-soft: rgba(239, 68, 68, 0.12);
  --shadow-lg: 0 20px 60px rgba(0, 0, 0, 0.55), 0 8px 24px rgba(0, 0, 0, 0.35);
  --radius: 14px;
  --radius-sm: 10px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: radial-gradient(1200px 700px at 80% -10%, rgba(108, 140, 255, 0.08), transparent 60%),
              radial-gradient(900px 600px at -10% 110%, rgba(239, 68, 68, 0.06), transparent 60%),
              var(--bg-0);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.55;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* Topbar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 28px;
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.7);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 600;
  letter-spacing: 0.2px;
}
.brand-mark {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: linear-gradient(135deg, #6c8cff, #b06cff);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.05) inset;
}
.brand-name span { color: var(--text-muted); font-weight: 400; }
.topbar-nav { display: flex; gap: 4px; }
.nav-link {
  color: var(--text-dim);
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 13px;
  transition: color .15s, background .15s;
}
.nav-link:hover { color: var(--text); background: var(--bg-2); }
.nav-link.active { color: var(--text); background: var(--bg-2); }
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #2c3346, #1b2030);
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  display: grid;
  place-items: center;
  border: 1px solid var(--border-strong);
}

/* Preview */
.preview {
  max-width: 980px;
  margin: 40px auto;
  padding: 0 24px;
}
.preview-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.image-wrap {
  background: #000;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}
.image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-top: 1px solid var(--border);
  background: linear-gradient(180deg, var(--bg-1), var(--bg-2));
}
.title {
  font-size: 18px;
  margin: 0 0 2px;
  font-weight: 600;
}
.subtitle {
  margin: 0;
  color: var(--text-muted);
  font-size: 12.5px;
}
.actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-3);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .15s, border-color .15s, transform .05s, color .15s;
}
.btn:hover { background: #232938; border-color: #3a4357; }
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(108, 140, 255, 0.35);
}
.btn-ghost { background: transparent; }
.btn-ghost:hover { background: var(--bg-3); }
.btn-danger {
  color: #fff;
  background: var(--danger);
  border-color: rgba(0,0,0,0.0);
  box-shadow: 0 1px 0 rgba(255,255,255,0.06) inset, 0 6px 18px rgba(239,68,68,0.25);
}
.btn-danger:hover { background: var(--danger-strong); }
.btn-danger:focus-visible { box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.4); }

/* Modal */
.modal[hidden] { display: none; }
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
  animation: fadeIn .15s ease-out;
}
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 10, 0.65);
  backdrop-filter: blur(6px);
}
.modal-panel {
  position: relative;
  width: 100%;
  max-width: 440px;
  background: linear-gradient(180deg, #181c26, #14171f);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 26px 26px 22px;
  box-shadow: var(--shadow-lg);
  animation: pop .18s cubic-bezier(.2,.9,.3,1.2);
}
.modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  background: transparent;
  border: none;
  color: var(--text-muted);
  border-radius: 8px;
  cursor: pointer;
  transition: color .15s, background .15s;
}
.modal-close:hover { color: var(--text); background: var(--bg-3); }
.modal-close:focus-visible { outline: none; box-shadow: 0 0 0 2px rgba(108,140,255,0.4); }

.modal-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: var(--danger-soft);
  color: var(--danger);
  margin-bottom: 14px;
  border: 1px solid rgba(239, 68, 68, 0.25);
}
.modal-title {
  font-size: 17px;
  font-weight: 600;
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}
.modal-desc {
  margin: 0 0 22px;
  color: var(--text-dim);
  font-size: 13.5px;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-3);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 10px 16px;
  border-radius: 10px;
  font-size: 13px;
  box-shadow: var(--shadow-lg);
  z-index: 200;
  animation: slideUp .2s ease-out;
}
.toast[hidden] { display: none; }

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop {
  from { opacity: 0; transform: translateY(6px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes slideUp {
  from { opacity: 0; transform: translate(-50%, 8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

@media (max-width: 560px) {
  .meta { flex-direction: column; align-items: stretch; }
  .actions { justify-content: flex-end; }
  .topbar-nav { display: none; }
}
