  -webkit-font-smoothing: antialiased;
}

/* Topbar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 28px;
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.7);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 600;
  letter-spacing: 0.2px;
}
.brand-mark {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: linear-gradient(135deg, #6c8cff, #b06cff);
  box-shadow: 0 0 0 1px rgba(255,255,255,0.05) inset;
}
.brand-name span { color: var(--text-muted); font-weight: 400; }
.topbar-nav { display: flex; gap: 4px; }
.nav-link {
  color: var(--text-dim);
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 13px;
  transition: color .15s, background .15s;
}
.nav-link:hover { color: var(--text); background: var(--bg-2); }
.nav-link.active { color: var(--text); background: var(--bg-2); }
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #2c3346, #1b2030);
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  display: grid;
  place-items: center;
  border: 1px solid var(--border-strong);
}

