.preview {
  max-width: 980px;
  margin: 40px auto;
  padding: 0 24px;
}
.preview-card {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.image-wrap {
  background: #000;
